// One folded sine wave around a circle, the same on every layer.
// Units: mm.

const n_tau = PI * 2;
const n_height = 100;
const n_its_layer = 20;
// Many corners: each wave needs about 40 to look round.
const n_its_corner = 320;
const n_height_cone = 0;
const n_height_dome = 0;
const n_overhang_dome = 33;

// The circle the wave runs along.
const n_radius = 34;
// How many waves go around it.
const n_its_wave =12;
// How far each wave goes in and out from the circle.
const n_amp = 12;
// How far the waves fold back. 0 is a plain sine wave. At 1 the
// flanks point straight at the axis. Above 1 they lean over and
// each wave becomes a loop. Near 5 neighbouring loops touch.
const n_fold = 3;

// The same as n_fold, as the angle the wall swings back and
// forth, in radians.
const n_back = n_fold / (2 * n_its_wave);

function f_o_p(n_it_layer_nor, n_it_corner_nor) {
    // How much of the wiggle this layer has: 0 at the bottom is a
    // circle, 1 at the top is the full folded wave.
    const n_grow = n_it_layer_nor;

    // How far along the wave this corner is: one full sine per wave.
    const n_phase = n_it_corner_nor * n_its_wave * n_tau;

    // In and out: the plain sine wave, grown by n_grow.
    const n_r = n_radius + n_amp * n_grow * sin(n_phase);

    // Around: a steady walk, minus the swing, grown the same way.
    let n_angle = n_it_corner_nor * n_tau
        - n_back * n_grow * sin(2 * n_phase);

    n_angle += n_it_layer_nor;
    return {
        n_x: sin(n_angle) * n_r,
        n_y: cos(n_angle) * n_r,
        n_z: o_thread.n_z + n_height_cone + n_it_layer_nor * n_height,
    };
}

return {
    n_its_layer, n_its_corner, f_o_p,
};
